static const char EK_ROOT_STAGE_SH[] = "#!/system/bin/sh\r\n# Runs after GRANT_ROOT, as the KernelSU root profile (uid 0, u:r:ksu:s0).\r\n# Installs the ksud userspace already staged by run.sh.\r\nset -u\r\nD=$(cd \"$(dirname \"$0\")\" && pwd)\r\nlog() { echo \"[stage] $*\"; }\r\n\r\nlog \"uid=$(id -u) ctx=$(cat /proc/self/attr/current)\"\r\nif grep -q '^kernelsu ' /proc/modules; then\r\n    log \"kernelsu live\"\r\nelse\r\n    log \"kernelsu missing\"\r\nfi\r\nif [ \"$(id -u)\" != \"0\" ]; then\r\n    log \"not uid 0\"\r\n    echo STAGE_FAIL\r\n    exit 1\r\nfi\r\n\r\nif [ -x \"$D/ksud\" ]; then\r\n    mkdir -p /data/adb/ksu/bin /data/adb/modules 2>>\"$D/root_stage.log\"\r\n    cp -f \"$D/ksud\" /data/adb/ksud 2>>\"$D/root_stage.log\"\r\n    chmod 755 /data/adb/ksud 2>>\"$D/root_stage.log\"\r\nfi\r\nif [ -x /data/adb/ksud ]; then\r\n    /data/adb/ksud install >>\"$D/root_stage.log\" 2>&1\r\n    log \"ksud_install_rc=$?\"\r\n    ln -sf /data/adb/ksud /data/adb/ksu/bin/su 2>>\"$D/root_stage.log\"\r\n    ln -sf /data/adb/ksud /data/adb/ksu/bin/ksud 2>>\"$D/root_stage.log\"\r\n    # Do not run \"ksud late-load\" here: it restarts the KernelSU manager,\r\n    # which launches the manager UI and re-enables shell_su_adb_only.\r\n    /data/adb/ksud feature set su_compat 1 >>\"$D/root_stage.log\" 2>&1\r\n    log \"su_compat_rc=$?\"\r\n    # Allow su from shell-uid processes spawned by the app/Shizuku, not only\r\n    # from an adbd or ksu ancestor (MagicRoot uses allow_shell the same way).\r\n    /data/adb/ksud feature set shell_su_adb_only 0 >>\"$D/root_stage.log\" 2>&1\r\n    log \"shell_su_adb_only_rc=$?\"\r\n    echo 1 > /sys/fs/selinux/enforce 2>>\"$D/root_stage.log\"\r\n    log \"enforce_rc=$? now=$(getenforce)\"\r\n    /data/adb/ksud debug mark refresh >>\"$D/root_stage.log\" 2>&1 || true\r\nelse\r\n    log \"ksud missing\"\r\n    echo STAGE_FAIL\r\n    exit 1\r\nfi\r\nlog \"id: $(id)\"\r\necho ROOT_STAGE_OK\r\n";
